lors.accent}\\n            opacity={m.summited ? 1 : 0.5}\\n          />\\n        ))}\\n      </RNMapView>\\n\\n      <View style={styles.mapLegend}>\\n        <View style={styles.legendItem}>\\n          <View style={[styles.legendDot, { backgroundColor: Colors.success }]} />\\n          <Text style={styles.legendText}>Summited</Text>\\n        </View>\\n        <View style={styles.legendItem}>\\n          <View style={[styles.legendDot, { backgroundColor: Colors.accent, opacity: 0.5 }]} />\\n          <Text style={styles.legendText}>Not Yet</Text>\\n        </View>\\n      </View>\\n    </View>\\n  );\\n}\\n\\nconst styles = StyleSheet.create({\\n  container: {\\n    flex: 1,\\n    backgroundColor: Colors.primary,\\n  },\\n  mapHeader: {\\n    position: 'absolute',\\n    top: 0,\\n    left: 0,\\n    right: 0,\\n    zIndex: 10,\\n    flexDirection: 'row',\\n    justifyContent: 'space-between',\\n    alignItems: 'center',\\n    paddingHorizontal: 20,\\n    paddingBottom: 10,\\n    backgroundColor: Colors.overlay,\\n  },\\n  mapTitle: {\\n    fontSize: 22,\\n    fontWeight: '800' as const,\\n    color: Colors.text,\\n  },\\n  mapBadge: {\\n    backgroundColor: Colors.accent + '20',\\n    paddingHorizontal: 12,\\n    paddingVertical: 6,\\n    borderRadius: 12,\\n    borderWidth: 1,\\n    borderColor: Colors.accent + '35',\\n  },\\n  mapBadgeText: {\\n    color: Colors.accentLight,\\n    fontSize: 12,\\n    fontWeight: '700' as const,\\n  },\\n  map: {\\n    flex: 1,\\n  },\\n  mapLegend: {\\n    position: 'absolute',\\n    bottom: 20,\\n    left: 20,\\n    flexDirection: 'row',\\n    gap: 16,\\n    backgroundColor: Colors.overlay,\\n    paddingHorizontal: 16,\\n    paddingVertical: 10,\\n    borderRadius: 12,\\n  },\\n  legendItem: {\\n    flexDirection: 'row',\\n    alignItems: 'center',\\n    gap: 6,\\n  },\\n  legendDot: {\\n    width: 10,\\n    height: 10,\\n    borderRadius: 5,\\n  },\\n  legendText: {\\n    color: Colors.text,\\n    fontSize: 12,\\n    fontWeight: '500' as const,\\n  },\\n  fallbackContainer: {\\n    flex: 1,\\n  },\\n  fallbackContent: {\\n    flex: 1,\\n    alignItems: 'center',\\n    paddingHorizontal: 24,\\n    paddingTop: 40,\\n  },\\n  fallbackIconWrap: {\\n    width: 72,\\n    height: 72,\\n    borderRadius: 36,\\n    backgroundColor: Colors.accent + '12',\\n    justifyContent: 'center',\\n    alignItems: 'center',\\n  },\\n  fallbackTitle: {\\n    fontSize: 24,\\n    fontWeight: '800' as const,\\n    color: Colors.text,\\n    marginTop: 16,\\n    marginBottom: 8,\\n  },\\n  fallbackSubtitle: {\\n    fontSize: 14,\\n    color: Colors.textSecondary,\\n    textAlign: 'center',\\n    marginBottom: 24,\\n    lineHeight: 20,\\n  },\\n  statsCard: {\\n    backgroundColor: Colors.cardBg,\\n    borderRadius: 16,\\n    padding: 24,\\n    alignItems: 'center',\\n    borderWidth: 1,\\n    borderColor: Colors.border,\\n    marginBottom: 24,\\n    width: '100%',\\n  },\\n  statsNumber: {\\n    fontSize: 48,\\n    fontWeight: '900' as const,\\n    color: Colors.accentLight,\\n  },\\n  statsLabel: {\\n    fontSize: 14,\\n    color: Colors.textSecondary,\\n    marginTop: 4,\\n  },\\n  summitList: {\\n    width: '100%',\\n    backgroundColor: Colors.cardBg,\\n    borderRadius: 16,\\n    padding: 16,\\n    borderWidth: 1,\\n    borderColor: Colors.border,\\n  },\\n  summitListTitle: {\\n    fontSize: 16,\\n    fontWeight: '700' as const,\\n    color: Colors.text,\\n    marginBottom: 12,\\n  },\\n  summitItem: {\\n    flexDirection: 'row',\\n    alignItems: 'center',\\n    paddingVertical: 10,\\n    borderBottomWidth: 1,\\n    borderBottomColor: Colors.border,\\n  },\\n  summitInfo: {\\n    flex: 1,\\n    marginLeft: 12,\\n  },\\n  summitName: {\\n    fontSize: 14,\\n    fontWeight: '600' as const,\\n    color: Colors.text,\\n  },\\n  summitLocation: {\\n    fontSize: 11,\\n    color: Colors.textMuted,\\n  },\\n  summitElev: {\\n    fontSize: 13,\\n    fontWeight: '700' as const,\\n    color: Colors.accentLight,\\n  