         ))}\n        </View>\n\n        <View style={styles.noteCard}>\n          <Text style={styles.noteTitle}>Key Facts</Text>\n          <Text style={styles.noteText}>\n            • The \"Death Zone\" begins above ~7,600m (25,000ft){'\\n'}\n            • Above this altitude, the body deteriorates faster than it can acclimatize{'\\n'}\n            • Most climbers use supplemental oxygen above 7,000m{'\\n'}\n            • Effective O₂ shows the equivalent oxygen percentage you'd breathe{'\\n'}\n            • Acclimatization allows the body to partially compensate\n          </Text>\n        </View>\n      </ScrollView>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  container: {\n    flex: 1,\n    backgroundColor: Colors.primary,\n  },\n  scrollView: {\n    flex: 1,\n  },\n  scrollContent: {\n    padding: 16,\n    paddingBottom: 40,\n  },\n  infoCard: {\n    backgroundColor: Colors.cardBg,\n    borderRadius: 16,\n    padding: 20,\n    alignItems: 'center',\n    borderWidth: 1,\n    borderColor: Colors.border,\n    marginBottom: 16,\n  },\n  infoIconWrap: {\n    width: 56,\n    height: 56,\n    borderRadius: 28,\n    backgroundColor: Colors.accent + '12',\n    justifyContent: 'center',\n    alignItems: 'center',\n    marginBottom: 4,\n  },\n  infoTitle: {\n    fontSize: 20,\n    fontWeight: '700' as const,\n    color: Colors.text,\n    marginTop: 10,\n    marginBottom: 8,\n  },\n  infoText: {\n    fontSize: 13,\n    color: Colors.textSecondary,\n    textAlign: 'center',\n    lineHeight: 20,\n  },\n  legendRow: {\n    flexDirection: 'row',\n    justifyContent: 'center',\n    gap: 16,\n    marginBottom: 16,\n  },\n  legendItem: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: 6,\n  },\n  legendDot: {\n    width: 10,\n    height: 10,\n    borderRadius: 5,\n  },\n  legendText: {\n    fontSize: 11,\n    color: Colors.textSecondary,\n  },\n  tableContainer: {\n    backgroundColor: Colors.cardBg,\n    borderRadius: 16,\n    overflow: 'hidden',\n    borderWidth: 1,\n    borderColor: Colors.border,\n    marginBottom: 16,\n  },\n  tableHeader: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    paddingHorizontal: 14,\n    paddingVertical: 12,\n    backgroundColor: Colors.cardBgLight,\n    borderBottomWidth: 1,\n    borderBottomColor: Colors.border,\n  },\n  tableHeaderText: {\n    fontSize: 11,\n    fontWeight: '700' as const,\n    color: Colors.textMuted,\n    textTransform: 'uppercase' as const,\n    letterSpacing: 0.5,\n  },\n  tableRow: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    paddingHorizontal: 14,\n    paddingVertical: 10,\n  },\n  tableRowAlt: {\n    backgroundColor: Colors.cardBgLight + '30',\n  },\n  colAlt: {\n    width: 80,\n  },\n  colO2: {\n    flex: 1,\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: 6,\n  },\n  colEff: {\n    width: 50,\n    textAlign: 'center',\n  },\n  colZone: {\n    width: 80,\n    alignItems: 'flex-end',\n  },\n  altPrimary: {\n    fontSize: 13,\n    fontWeight: '700' as const,\n    color: Colors.accentLight,\n  },\n  altSecondary: {\n    fontSize: 10,\n    color: Colors.textMuted,\n  },\n  o2BarContainer: {\n    flex: 1,\n    height: 6,\n    backgroundColor: Colors.primary,\n    borderRadius: 3,\n    overflow: 'hidden',\n  },\n  o2Bar: {\n    height: '100%',\n    borderRadius: 3,\n  },\n  o2Text: {\n    fontSize: 12,\n    fontWeight: '700' as const,\n    color: Colors.text,\n    width: 32,\n    textAlign: 'right',\n  },\n  effText: {\n    fontSize: 12,\n    color: Colors.textSecondary,\n    fontWeight: '600' as const,\n  },\n  zoneBadge: {\n    paddingHorizontal: 8,\n    paddingVertical: 3,\n    borderRadius: 6,\n    borderWidth: 1,\n  },\n  zoneText: {\n    fontSize: 9,\n    fontWeight: '700' as const,\n  },\n  noteCard: {\n    backgroundColor: Colors.cardBg,\n    borderRadius: 16,\n    padding: 20,\n    borderWidth: 1,\n    borderColor: Colors.border,\n  },\n  noteTitle: {\n    fontSize: 16,\n    fontWeight: '700' as const,\n    color: Colors.text,\n    marginBottom: 10,\n  },\n  noteText: {\n    fontSize: 13,\n    color: Colors.textSecondary,\n    lineHeight: 22,\n  },\n});\n",
